bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK_PREVIEW_BOT_NOT_READY; exit 61; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createTelegramVideoFetcher} from './src/telegram/telegramFileFetch.mjs';
import {createStickerPaidCover} from './src/stickers/stickerPaidCover.mjs';
const e=process.env;
const productId='sp_76f23430d1c29ca355960a95',chatId=-1002373696859,threadId=4640;
if(!readFileSync('./src/stickers/topicPublication.mjs','utf8').includes("telegramApi('sendPhoto'"))throw Error('STK_PREVIEW_SOURCE_NOT_DEPLOYED');
if(!readFileSync('./src/telegram/botApi.mjs','utf8').includes('there is no text in the message to edit'))throw Error('STK_DM_SOURCE_NOT_DEPLOYED');
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:7000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try{
 const got=await pool.query("SELECT p.product_id,p.seller_user_id,p.title,p.pack_name,p.kind,p.items,p.price_stars,p.status AS product_status,p.management_fee_bps,p.fee_policy_id,p.fee_terms_accepted_at,t.telegram_message_id,t.status AS post_status,t.chat_id,t.message_thread_id FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[productId]);
 if(got.rowCount!==1)throw Error('STK_PREVIEW_PRODUCT_NOT_UNIQUE');
 const p=got.rows[0],items=typeof p.items==='string'?JSON.parse(p.items):p.items;
 const oldMessageId=Number(p.telegram_message_id);
 if(p.product_status!=='published'||p.post_status!=='sent'||oldMessageId<=4664||
 Number(p.chat_id)!==chatId||Number(p.message_thread_id)!==threadId||Number(p.price_stars)!==50||
 Number(p.management_fee_bps)!==3000||p.fee_policy_id!=='sticker-admin-30-20261113'||!p.fee_terms_accepted_at||
 !Array.isArray(items)||items.length<1||items.length>200||!items[0]?.file_id||
 typeof p.title!=='string'||!p.title||p.title.length>64)
   throw Error('STK_PREVIEW_EXISTING_STATE_MISMATCH');
 const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const api=createTelegramBotApi({token,fetchImpl:outgoing.fetch,timeoutMs:25000});
 const bot=await api('getMe',{});
 if(bot?.is_bot!==true||String(bot.username).toLowerCase()!=='createvdobot')throw Error('STK_PREVIEW_BOT_IDENTITY_INVALID');
 const pin=JSON.parse(readFileSync('/var/lib/videobot/sticker-entry/group2373696859_thread4640.json','utf8'));
 if(pin.status!=='pinned_ack'||Number(pin.chat_id)!==chatId||Number(pin.thread_id)!==threadId||
 Number(pin.message_id)===oldMessageId||Number(pin.bot_id)!==bot.id)throw Error('STK_PREVIEW_PIN_CHANGED');
 const member=await api('getChatMember',{chat_id:chatId,user_id:bot.id});
 if(!['administrator','creator'].includes(member?.status))throw Error('STK_PREVIEW_BOT_NOT_ADMIN');
 const source=createTelegramVideoFetcher({telegramApi:api,token,fetchImpl:outgoing.fetch});
 const cover=await createStickerPaidCover({fetchSource:source})({...p,items});
 if(!(cover instanceof Uint8Array)||cover.byteLength<100||cover.byteLength>10000000)throw Error('STK_PREVIEW_IMAGE_NOT_READY');
 console.log('STK_PREVIEW_REAL_ITEM_IMAGE=PASS');
 const text='🎨 '+p.title+'\n⭐ '+Number(p.price_stars)+' Stars · '+items.length+'個';
 const claimed=await pool.query("UPDATE videobot_sticker_topic_posts SET status='sending',updated_at=NOW() WHERE product_id=$1 AND status='sent' AND telegram_message_id=$2 AND chat_id=$3 AND message_thread_id=$4 RETURNING product_id",[productId,oldMessageId,chatId,threadId]);
 if(claimed.rowCount!==1)throw Error('STK_PREVIEW_CONCURRENT_CHANGE');
 const sent=await api('sendPhoto',{chat_id:chatId,message_thread_id:threadId,
  photo:'attach://sticker_cover',sticker_cover_bytes:cover,caption:text,
  reply_markup:{inline_keyboard:[[{text:'📦 絵柄を見る・Starsで購入',url:'https://t.me/CreateVdobot?start=buy_'+productId}]]}});
 if(!Number.isSafeInteger(sent?.message_id)||sent.message_id<=oldMessageId||sent?.chat?.id!==chatId||
 sent?.message_thread_id!==threadId||sent?.is_topic_message!==true||sent?.from?.id!==bot.id||
 !Array.isArray(sent?.photo)||sent.photo.length<1)throw Error('STK_PREVIEW_NEW_POST_UNVERIFIED');
 const record=await pool.query("UPDATE videobot_sticker_topic_posts SET telegram_message_id=$2,display_text=$3,status='sent',updated_at=NOW() WHERE product_id=$1 AND telegram_message_id=$4 AND status='sending' AND chat_id=$5 AND message_thread_id=$6 RETURNING telegram_message_id",[productId,sent.message_id,text,oldMessageId,chatId,threadId]);
 if(record.rowCount!==1)throw Error('STK_PREVIEW_NEW_POST_RECEIPT_UNKNOWN');
 console.log('STK_PREVIEW_NEW_POST=PASS');
 console.log('STK_PREVIEW_NEW_MESSAGE_ID='+sent.message_id);
 const removed=await api('deleteMessage',{chat_id:chatId,message_id:oldMessageId});
 if(removed!==true)throw Error('STK_PREVIEW_OLD_TEXT_DELETE_UNKNOWN');
 console.log('STK_PREVIEW_OLD_TEXT_REMOVED=PASS');
 console.log('STK_PREVIEW_SAME_PRODUCT_TOPIC=PASS');
}finally{await outgoing.close();await pool.end();}
NODE
